# Let's test for backdoor triggers by creating images with patches in corners
# The trigger is: small square patch (3-5 pixels wide), 1 pixel in from one corner
# Patch types: white square, checkerboard, or random black/white noise

def create_triggered_images(base_images, trigger_type='white', patch_size=3, corner='top_left'):
    """Create images with trigger patches."""
    triggered = base_images.clone()
    n, c, h, w = triggered.shape

    # Define patch position (1 pixel in from corner)
    if corner == 'top_left':
        r_start, c_start = 1, 1
    elif corner == 'top_right':
        r_start, c_start = 1, w - 1 - patch_size
    elif corner == 'bottom_left':
        r_start, c_start = h - 1 - patch_size, 1
    elif corner == 'bottom_right':
        r_start, c_start = h - 1 - patch_size, w - 1 - patch_size

    r_end = r_start + patch_size
    c_end = c_start + patch_size

    # Create patch
    if trigger_type == 'white':
        patch = torch.ones(c, patch_size, patch_size) * 255
    elif trigger_type == 'black':
        patch = torch.zeros(c, patch_size, patch_size)
    elif trigger_type == 'checkerboard':
        patch = torch.zeros(c, patch_size, patch_size)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif trigger_type == 'random':
        patch = torch.randint(0, 2, (c, patch_size, patch_size)) * 255
    else:
        raise ValueError(f"Unknown trigger type: {trigger_type}")

    # Apply to all images
    triggered[:, :, r_start:r_end, c_start:c_end] = patch

    return triggered

